CLAUDE_CONFIG_DIR=
CLAUDE_CONFIG_DIR=/workspace/.claude
CLAUDE_CODE_ENTRYPOINT=cli
CLAUDECODE=1
---
{
  "name": "Claude Code Sandbox",
  "build": {
    "dockerfile": "Dockerfile",
    "context": "."
  },
  "remoteUser": "vscode",
  "containerUser": "vscode",
  "workspaceFolder": "/workspace",
  "workspaceMount": "source=${localWorkspaceFolder},target=/workspace,type=bind,consistency=cached",

  "capAdd": ["NET_ADMIN", "NET_RAW"],

  "mounts": [
    "source=claude-code-starter-bashhistory,target=/home/vscode/.bash_history,type=volume",
    "source=/var/run/docker.sock,target=/var/run/docker.sock,type=bind",
    "source=${localEnv:HOME}/.config/helix,target=/home/vscode/.config/helix,type=bind,consistency=cached",
    "source=${localEnv:HOME}/.gitconfig,target=/tmp/.host-gitconfig,type=bind,consistency=cached"
  ],

  "containerEnv": {
    "CLAUDE_CONFIG_DIR": "/workspace/.claude",
    "EDITOR": "hx",
    "VISUAL": "hx",
    "COLORTERM": "truecolor"
  },

  "postStartCommand": "cp /tmp/.host-gitconfig /home/vscode/.gitconfig 2>/dev/null || true && sudo /usr/local/bin/init-firewall.sh && tmux new-session -d -s main",
  "waitFor": "postStartCommand",

  "customizations": {
    "vscode": {
      "extensions": [
        "anthropic.claude-code",
        "dbaeumer.vscode-eslint",
        "esbenp.prettier-vscode",
        "eamodio.gitlens"
      ],
      "settings": {
        "terminal.integrated.defaultProfile.linux": "zsh",
        "editor.formatOnSave": true,
        "editor.defaultFormatter": "esbenp.prettier-vscode"
      }
    }
  }
}

